function [m] = dump(hdev, ht, b, k, m_max)
%DUMP  The coil dipole that dumps the device momentum toward its target: m = k (H - H_t) x B/|B|^2,
%   saturated; no field, no dipole.
%   hdev: real[1][3] (passed a plain number)
%   ht: real[1][3] (passed a plain number)
%   b: real[1][3] (passed a plain number)
%   k: real[1] (passed a plain number)
%   m_max: real[1] (passed a plain number)
%   returns m: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 1);
    bs = (b(1)*b(1) + b(2)*b(2) + b(3)*b(3));
    if (bs < 1e-18)
        m = zeros(3, 1);
    else
        h__92 = (hdev - ht);
        m = asils.alg.control.sat_dipole(([h__92(2)*b(3) - h__92(3)*b(2); h__92(3)*b(1) - h__92(1)*b(3); h__92(1)*b(2) - h__92(2)*b(1)] * (k / bs)), m_max);
    end
end
